SELECT rr.* FROM referral_reward rr
INNER JOIN referral_record r ON rr.referral_record_id = r.id
WHERE r.referrer_id = #{referrerId}
ORDER BY rr.created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

